const levels = [
  {roman:'I',name:'Я осознаю',question:'Где я?',key:'Ясности',guardian:'Правды',symbol:'✧',result:'Точка А: запрос, текущее состояние, эмоция, телесная зона и осознание.',rule:'Бросьте D6 и двигайтесь по кругу. Диагностика, совместимые Особые события и Другой взгляд открывают карты из подключенных колод. Осознание сохраняется в журнале, Хранитель Правды помогает сформулировать главный итог.',decks:[['Диагностика','24','Основная колода'],['Особое событие','24','Дополнительная'],['Другой взгляд','50','Дополнительная']]},
  {roman:'II',name:'Я выбираю',question:'Что мне нужно?',key:'Потребности',guardian:'Выбора',symbol:'◇',result:'Сформулирована моя истинная потребность.',rule:'Игровой круг второго уровня подключен: карты Потребностей, Ключ, Хранитель выбора и итоговая Карта потребностей.',decks:[['Потребности','35','Основная колода'],['Другой взгляд','50','Дополнительная'],['Особое событие','24','Дополнительная']]},
  {roman:'III',name:'Я принимаю',question:'Что я отрицаю?',key:'Принятия',guardian:'Истины',symbol:'◈',result:'Признанная Тень и присвоенная Сила.',rule:'Игровой круг третьего уровня подключен: 20 клеток и Портал, Тень ↔ Сила, Поддержка, Хранитель истины и Карта принятия.',decks:[['Тень ↔ Сила','60','Основная двусторонняя колода'],['Другой взгляд','50','Дополнительная'],['Особое событие','24','Дополнительная'],['Богини / Архетипы силы','20','Поддержка']]},
  {roman:'IV',name:'Я возвращаю',question:'Где моя энергия / внимание?',key:'Энергии',guardian:'Истины',symbol:'✺',result:'Возвращено внимание и собран доступный ресурс.',rule:'Возвращение энергии становится основной практикой. Архетипы силы продолжают поддерживать игрока. Игровой круг: 20 клеток и Портал. Основная колода «Возвращение энергии», поддержка Архетипов силы, Ключ Энергии и Хранитель истины.',decks:[['Возвращение энергии','24','Основная колода'],['Другой взгляд','50','Дополнительная'],['Особое событие','24','Дополнительная'],['Богини / Архетипы силы','20','Поддержка']]},
  {roman:'V',name:'Я создаю',question:'Что я создаю?',key:'Воплощения',guardian:'Будущего',symbol:'✦',result:'Точка Б: выбор направления, распределение энергии и первый шаг.',rule:'Вход возможен при Ключе IV уровня и запасе не менее 25 ⚡. Игровой круг пятого уровня подключен. Портал ведет в Центр; его сценарий ожидает отдельного утверждения.',decks:[['Творение','24','Основная колода'],['Богини / Архетипы силы','20','Поддержка'],['Особое событие','24','Дополнительная']]}
];
const decks = [
  ['Диагностика','24','I · Осознание','Состояние, эмоции, телесный сигнал и Точка А.'],
  ['Потребности','35','II · Выбор','Истинная потребность за внешним желанием.'],
  ['Тень ↔ Сила','60','III · Принятие','Две стороны карты: Тень и раскрытая Сила.'],
  ['Другой взгляд','50','I–IV · Дополнительная','Смена привычной перспективы.'],
  ['Возвращение энергии','24','IV · Возвращение','Практики и вопросы для возврата внимания.'],
  ['Творение','24','V · Создание','Выбор, состояние, энергия, намерение, действие, финал.'],
  ['Особое событие','24','I–V · Дополнительная','Обстоятельства, влияющие на игровой маршрут.'],
  ['Богини / Архетипы силы','20','III–V · Поддержка','Ресурсные качества и образы поддержки.']
];
const objects = [
  ['Игровое поле','5 кругов','Круги I–V подключены; Центр ожидает отдельный сценарий.'],
  ['Кубик D6','1','Автоматически задает движение по кругу.'],
  ['Фишка игрока','1–6','Показывает текущую позицию.'],
  ['Энергия','⚡','Сквозной игровой ресурс, баланс не бывает отрицательным.'],
  ['Ключи','5 типов','Открывают право выбора перехода у Портала.'],
  ['Порталы','5','Вход и переход каждого круга.'],
  ['Хранители','5','Смысловые точки уровней.'],
  ['Журнал осознаний','1 на игрока','Сохраняет записанные выводы.'],
  ['Грани Кристалла','30','Физический компонент; цифровая функция пока не задана.'],
  ['Центральный Кристалл','1','Физический символ финала.'],
  ['Сакральные символы','18','Физический компонент; цифровая функция пока не задана.']
];
let selected=0;
const el=id=>document.getElementById(id);
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderRoute(){el('route').innerHTML=levels.map((l,i)=>`<button class="stage" type="button" aria-pressed="${i===selected}" data-level="${i}"><span class="stage-top"><span class="stage-number">${l.roman}</span><span class="stage-glyph" aria-hidden="true">${l.symbol}</span></span><span class="stage-title">${l.name}</span><span class="stage-question">${l.question}</span><span class="stage-foot">Ключ ${l.key} · Портал ${i+1}</span></button>`).join('')}
function renderLevel(){const l=levels[selected];el('level-panel').innerHTML=`<div class="level-banner"><div class="level-kicker">Уровень ${l.roman} / пять шагов</div><h2>${l.name}</h2><p>${l.question}</p></div><div class="level-body"><span class="mini-label">Итог уровня</span><div class="result-box">${l.result}</div><div class="two-col"><section class="detail-block"><h3>Как проходит уровень</h3><p>${l.rule}</p><div class="guardian"><span class="mini-label">Хранитель ${l.guardian}</span><p>Проверка результата уровня; точный протокол для II–V будет добавлен после утверждения.</p></div></section><section class="detail-block"><h3>Колоды уровня</h3><div class="deck-list">${l.decks.map(d=>`<div class="deck-row"><div><strong>${safe(d[0])}</strong><small>${safe(d[2])}</small></div><span class="count">${safe(d[1])}</span></div>`).join('')}</div></section></div></div>`}
el('route').addEventListener('click',e=>{const b=e.target.closest('[data-level]');if(!b)return;selected=Number(b.dataset.level);renderRoute();renderLevel()});
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>t.setAttribute('aria-selected',String(t===b)));for(const id of ['play','explore','catalog'])el(id).hidden=b.getAttribute('aria-controls')!==id}));
el('deck-catalog').innerHTML=decks.map(d=>`<article class="catalog-item"><span class="category">${safe(d[2])}</span><h3>${safe(d[0])}</h3><p>${safe(d[3])}</p><span class="item-foot">${safe(d[1])} карт</span></article>`).join('');
el('object-catalog').innerHTML=objects.map(o=>`<article class="catalog-item special"><span class="category">Игровой объект</span><h3>${safe(o[0])}</h3><p>${safe(o[2])}</p><span class="item-foot">${safe(o[1])}</span></article>`).join('');
renderRoute();renderLevel();
